-- Read-back after block 2a (+ 2b). Run: node scripts/verification/prod-query.mjs scripts/verification/apply/readback-fll-gar-coverage-block2.sql
-- Expected after 2a: 43 fields listed (all active, is_required false, verified_against_standard), 1 equation FLL-GAR-06-D1, bahn_vorkonfektioniert 'ja' label starts with "ja —".
select w.code ws, f.symbol, f.data_type, f.unit, f.widget, f.visible_when, f.is_required, f.verification_status, f.order_index
  from fields f join worksheet_templates w on w.id = f.worksheet_template_id join standards s on s.id = w.standard_id
 where s.code = 'FLL-GAR-2023' and f.symbol in ('baugrund_ev2_mpa', 'baugrund_ev1_mpa', 'baugrund_ev2_ev1', 'baugrund_dpr_pct', 'einbauwassergehalt_w_pct', 'w_pr_pct', 'w_097pr_pct', 'luftporenanteil_na_pct', 'pe_nenndicke_mm', 'peeh_russverteilung_kat', 'peeh_massaenderung_pct', 'peeh_nctl_h', 'peeh_oit_min', 'peeh_bbodschv_unbedenklich', 'pe_boeschung_strukturiert', 'pe_querueberlappung_vermieden', 'pe_bermen_vorgesehen', 'pe_scherversuch_durchgefuehrt', 'pe_probeschweissung_durchgefuehrt', 'pe_probeschweissung_laenge_m', 'pe_probeschweissung_breite_cm', 'pe_nahtpruefung_verfahren', 'pe_nahtpruefung_protokoll', 'pe_riss_entstehung_mm', 'pe_riss_aufweitung_mm', 'pe_riss_versatz_mm', 'as_schichtdicke_cm', 'as_lockerungstiefe_cm', 'as_dpr_pct', 'as_kf_m_s', 'as_organische_substanz_VGL', 'as_kalkgehalt_VCA', 'wurzelfestigkeit_testat_quecken', 'rhizomfestigkeit_gewaesser_pruefung', 'sl_baugrund_groesstkorn_mm', 'sl_schutzlage_unten_dicke_cm', 'sl_ueberlappung_cm', 'sl_pruefzeugnis_swk', 'randbefestigung_angepasst', 'gewaesser_an_gebaeudeteilen', 'notueberlauf_vorhanden', 'notueberlauf_kapazitaet_l_s', 'notueberlauf_hoeher_als_regelueberlauf') order by w.code, f.order_index;
select w.code ws, e.equation_number, e.formula from equations e join worksheet_templates w on w.id = e.worksheet_template_id join standards s on s.id = w.standard_id where s.code = 'FLL-GAR-2023' and e.equation_number = 'FLL-GAR-06-D1';
select f.enum_values->0->>'label_de' ja_label from fields f join worksheet_templates w on w.id = f.worksheet_template_id join standards s on s.id = w.standard_id where s.code = 'FLL-GAR-2023' and w.code = 'FLL-GAR-16' and f.symbol = 'bahn_vorkonfektioniert';
-- Expected after 2b: REQ-18 on FLL-GAR-16, REQ-22 on FLL-GAR-20, REQ-11/REQ-24 non-empty, REQ-31…REQ-40 present (10 new).
select w.code ws, cr.code, cr.severity, cr.condition from compliance_requirements cr join worksheet_templates w on w.id = cr.worksheet_template_id join standards s on s.id = w.standard_id
 where s.code = 'FLL-GAR-2023' and cr.code in ('REQ-11','REQ-12','REQ-18','REQ-20','REQ-22','REQ-23','REQ-24','REQ-31','REQ-32','REQ-33','REQ-34','REQ-35','REQ-36','REQ-37','REQ-38','REQ-39','REQ-40') order by cr.code;
